const lockProjectForTaskNumber = `-- name: LockProjectForTaskNumber :one
SELECT id
FROM projects
WHERE workspace_id = ?
  AND id = ?
  AND enabled = TRUE
FOR UPDATE
`

type LockProjectForTaskNumberParams struct {
	WorkspaceID uint32 `json:"-"`
	ID          uint32 `json:"-"`
}

// Lock the owning project row before task-number allocation. This serializes
// concurrent creators for the same project while still allowing different
// projects to allocate independently.
func (q *Queries) LockProjectForTaskNumber(ctx context.Context, arg LockProjectForTaskNumberParams) (uint32, error) {
	row := q.db.QueryRowContext(ctx, lockProjectForTaskNumber, arg.WorkspaceID, arg.ID)
	var id uint32
	err := row.Scan(&id)
	return id, err
}

const resolveTaskRef = `-- name: ResolveTaskRef :one
SELECT
  t.id,
  t.public_id,
  t.workspace_id,
  t.title
FROM tasks t
INNER JOIN projects p ON p.id = t.project_id AND p.enabled = TRUE
WHERE p.workspace_id = ?
  AND p.identifier = ?
  AND t.task_number = ?
  AND t.enabled = TRUE
LIMIT 1
`

type ResolveTaskRefParams struct {
	WorkspaceID uint32         `json:"-"`
	Identifier  sql.NullString `json:"identifier"`
	TaskNumber  uint32         `json:"taskNumber"`
}

type ResolveTaskRefRow struct {
	ID          uint32         `json:"-"`
	PublicID    types.PublicID `json:"publicId"`
	WorkspaceID uint32         `json:"-"`
	Title       string         `json:"title"`
}

// Resolve a human-readable task reference (e.g. NF-42) to a task public_id.
// task-visibility: not-applicable — the only caller re-resolves the task it
// finds through the shared task ACL and returns the error before the title
// reaches the caller, so a task the actor may not see is answered as missing.
func (q *Queries) ResolveTaskRef(ctx context.Context, arg ResolveTaskRefParams) (ResolveTaskRefRow, error) {
	row := q.db.QueryRowContext(ctx, resolveTaskRef, arg.WorkspaceID, arg.Identifier, arg.TaskNumber)
	var i ResolveTaskRefRow
	err := row.Scan(
		&i.ID,
		&i.PublicID,
		&i.WorkspaceID,
		&i.Title,
	)
	return i, err
}

const setTaskNumber = `-- name: SetTaskNumber :exec
UPDATE tasks
SET task_number = ?,
    updated_by_user_id = ?
WHERE id = ?
  AND workspace_id = ?
`

type SetTaskNumberParams struct {
	TaskNumber      uint32        `json:"taskNumber"`
	UpdatedByUserID sql.NullInt32 `json:"-"`
	ID              uint32        `json:"-"`
	WorkspaceID     uint32        `json:"-"`
}

// Set the task_number after allocation.
// updated_by_user_id is appended so the audit field records who allocated
// the number; in practice this runs in the same transaction as CreateTask
// so the same actor id is reused (NULL for system writers).
// workspace_id is required to ensure the update never crosses workspace
// boundaries even if the caller passes a foreign tasks.id.
func (q *Queries) SetTaskNumber(ctx context.Context, arg SetTaskNumberParams) error {
	_, err := q.db.ExecContext(ctx, setTaskNumber,
		arg.TaskNumber,
		arg.UpdatedByUserID,
		arg.ID,
		arg.WorkspaceID,
	)
	return err
}

const transitionTaskState = `-- name: TransitionTaskState :execrows
UPDATE tasks
SET derived_state = ?,
    completed_at = CASE WHEN ? = 'done' THEN CURRENT_TIMESTAMP ELSE NULL END,
    updated_by_user_id = ?
WHERE workspace_id = ?
  AND public_id = ?
  AND enabled = TRUE
`

type TransitionTaskStateParams struct {
	DerivedState    TasksDerivedState `json:"derivedState"`
	Column2         interface{}       `json:"column2"`
	UpdatedByUserID sql.NullInt32     `json:"-"`
	WorkspaceID     uint32            `json:"-"`
	PublicID        types.PublicID    `json:"publicId"`
}

// Write the new derived_state computed by the transition handler. This is
// the only path allowed to mutate derived_state and must be called inside
// the same transaction as the events append.
// updated_by_user_id is appended so the audit field reflects who triggered
// the transition (NULL for system writers / event-bus replays).
func (q *Queries) TransitionTaskState(ctx context.Context, arg TransitionTaskStateParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, transitionTaskState,
		arg.DerivedState,
		arg.Column2,
		arg.UpdatedByUserID,
		arg.WorkspaceID,
		arg.PublicID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

